TLM.f("Commune/C2c",{"officium":"Commune Unius Martyris Pontificis: Statuit","rule":[],"sections":{"Introitus":[{"k":"ref","la":"Eccli 45:30"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Infirmitátem nostram réspice, omnípotens Deus: et, quia pondus própriæ actiónis gravat, beáti N. Mártyris tui atque Pontíficis intercéssio gloriósa nos prótegat."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Jacóbi Apóstoli"},{"k":"ref","la":"Jac 1:12-18"},{"k":"text","la":"Caríssimi: Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ, quam repromísit Deus diligéntibus se. Nemo, cum tentátur, dicat, quóniam a Deo tentátur: Deus enim intentátor malórum est: ipse autem néminem tentat. Unusquísque vero tentátur a concupiscéntia sua abstráctus et illéctus. Deinde Concupiscéntia cum concéperit, parit peccátum: peccátum vero cum consummátum fúerit, génerat mortem. Nolíte itaque erráre, fratres mei dilectíssimi. Omne datum óptimum et omne donum perféctum desúrsum est, descéndens a Patre lúminum, apud quem non est transmutátio nec vicissitúdinis obumbrátio. Voluntárie enim génuit nos verbo veritátis, ut simus inítium aliquod creatúræ ejus."}],"Graduale":[{"k":"ref","la":"Ps 88:21-23"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum."},{"k":"text","la":"Nihil profíciet inimícus in eo, et fílius iniquitátis non nocébit ei. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Jurávit Dóminus, et non pœnitébit eum: Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 88:21-23"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum."},{"k":"text","la":"Nihil profíciet inimícus in eo, et fílius iniquitátis non nocébit ei.","mark":"V"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 14:26-33"},{"k":"text","la":"In illo témpore: Dixit Jesus turbis: Si quis venit ad me, et non odit patrem suum, et matrem, et uxórem, et fílios, et fratres, et soróres, adhuc autem et ánimam suam, non potest meus esse discípulus. Et qui non bájulat crucem suam, et venit post me, non potest meus esse discípulus. Quis enim ex vobis volens turrim ædificáre, non prius sedens cómputat sumptus, qui necessárii sunt, si hábeat ad perficiéndum; ne, posteáquam posúerit fundaméntum, et non potúerit perfícere, omnes, qui vident, incípiant illúdere ei, dicéntes: Quia hic homo cœpit ædificáre, et non pótuit consummáre? Aut quis rex itúrus commíttere bellum advérsus álium regem, non sedens prius cógitat, si possit cum decem mílibus occúrrere ei, qui cum vigínti mílibus venit ad se? Alióquin, adhuc illo longe agénte, legatiónem mittens, rogat ea, quæ pacis sunt. Sic ergo omnis ex vobis, qui non renúntiat ómnibus, quæ póssidet, non potest meus esse discípulus."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, beáti N. Mártyris tui atque Pontíficis dicátas méritis, benígnus assúme: et ad perpétuum nobis tríbue proveníre subsídium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 88:36; 88:37-38"},{"k":"text","la":"Semel jurávi in sancto meo: Semen ejus in ætérnum manébit: et sedes ejus sicut sol in conspéctu meo, et sicut luna perfécta in ætérnum, et testis in coelo fidélis. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refécti participatióne múneris sacri, quǽsumus, Dómine, Deus noster: ut, cujus exséquimur cultum, intercedénte beáto N. Mártyre tuo atque Pontífice, sentiámus efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"c02c414c737dacfd":{"t":"Sir 45, 30, Ps 131, 1\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu. (Ps 131, 1) Spomeni se, Gospodine, Davida i sve njegove krotkosti.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu.","kn":"(Grkv. 45, 30). Gospodin je sklopio s njime savez mira i učinio ga knezom, da zauvijek bude u svećeničkom dostojanstvu. (Ps. 131, 1). Sjeti se, Gospodine, Davida i sve njegove pobožnosti. Slava Ocu. Gospodin ...","knRef":"Kniewald 1942, str. 478–479 (snimka 240) (OCR)"},"830835cc8a13d993":{"kn":"Obazri se, svemogući Bože, na slabost Tvojih vjernika, koje pritište teret vlastitih čina i podaj, da nas zaštiti slavni zagovor blaženoga Alojzija, Tvoga mučenika i biskupa.\n<i>Po G. n.</i>","knRef":"Kniewald 1942, str. 789"},"17e7a4be818977b3":{"kn":"Čitanje poslanice bl. Jakova apostola (1, 12-18).\nPredragi! Blago čovjeku, koji izdrži napast, jer kad bude prokušan, primit će vijenac života, koji je Bog obećao onima, koji ga ljube. Neka nitko ne kaže, kada bude kušan, da ga Bog napastuje, jer Bog ne kuša na zlo, on ne napastuje nikoga, nego svakoga napastuje njegova požuda, koja ga vuče i mami. Požuda, kad joj se udovolji, rađa grijehom, a grijeh izvršen rađa smrću. Zato se, moja predraga braćo, ne varajte! Svaki dobri dar i svaki savršeni poklon je odozgo i dolazi od Oca svijetla, kod koga nema promjene ni zasjenke mijene. On nas je dragovoljno rodio po riječi istine, da budemo kao prvenci njegovih stvorova.","knRef":"Kniewald 1942, str. 789"},"cf331c57e9268245":{"t":"Ps 88, 21-23\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja. Neprijatelj biti nemoćan prema njemu, i sin bezakonja neće se usuditi da mu naškodi.\n\nPs 20, 3-4\nTi si mu ispunio želju njegova srca i nisi mu uskratio molbe njegovih usana. Pretekao si ga slatkim blagoslovom. Postavio si mu na glavu vijenac od dragog kamenja."},"80912993d51d297a":{"t":"Lk 14, 26-33\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus narodu: Ako tko dolazi k meni, a ne ostavi svojega oca i majku, ženu i djecu, braću i sestre, pa i samoga sebe, ne može biti moj učenik. I tko ne nosi svoj križ i ne pođe za mnom, ne može biti moj učenik. Jer kad tko od vas odluči sazidati kulu, zar najprije ne sjedne i ne računa, koliko treba troškova da mogne dovršiti, da mu se svi koji vide kako je postavio temelje a nije dovršio, ne stanu rugati: Ovaj je čovjek počeo zidati, a nije mogao dovršiti? Ili koji vladar kad polazi u rat protiv drugoga vladara, zar ne sjedne prije i ne razmišlja, može li se s deset tisuća oprijeti onome koji dolazi protiv njega s dvadeset tisuća? Inače, dok je onaj još daleko, uputit će poslanike i moliti mir. Tako isto nitko od vas koji se ne odreče svega što ima, ne može biti moj učenik.","kn":"t Slijedi sveto evanđelje po Lnki (14, 26-33). U ono vrijeme reče Isus narodu; Ako tko dolazi k meni, a ne mrzi svojega oca i majke i žene i djece i braće i sestara, pa i samoga sebe, ne može biti moj učenik. I tko ne nosi svojega križa i ne ide za mnom, ne može biti moj učenik. Jer tko od vas hoteći graditi kulu, najprije ne sjedne i računa, koliko treba troška, da mogne dovršiti, da mu se svi, koji vide, da je postavio temelje, a nije dovršio, ne počnu rugati i govoriti: Ovaj je čovjek počeo graditi, a nije mogao dovršiti. Ili koji kralj, kad ide ratovati protiv drugoga kralja, ne sjedne prije i promisli, da li se može oprijeti s deset tisuća onomu, koji dolazi na njega s dvadeset tisuća.' Jer će inače, dok je onaj još daleko, uputiti poslanike i moliti za mir. Isto tako nitko od vas, koji se ne odreče svega, što ima, ne može biti moj učenik.","knRef":"Kniewald 1942, str. 542–543 (snimka 272) (OCR)"},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć.","kn":"(Ps. 88, 25). Istina je moja i milosrđe moje B njime i u ime će se moje uzdići moć njegova.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"78819bb68ebaf436":{"kn":"Primi, Gospodine, blagostivo žrtve, što Ti ih prinosimo zaslugama blaženoga Alojzija, Tvoga mučenika i biskupa i podaj, da nam ishode neprestanu Tvoju pomoć.\n<i>Po G. n.</i>","knRef":"Kniewald 1942, str. 790"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"3eefd390cb354c24":{"t":"Ps 88, 36-38\nZakleo sam se svecu svome: Potomstvo će njegovo ostati dovijeka. I prijestolje će njegovo biti kao sunce, kao puni mjesec u vijeke i kao duga koja je vjeran znak na nebesima.","kn":"(Ps. 88, 36-38). Jednom se zakleh svetošću svojom: potomstvo će njegovo ostati u vijeke, i prijesto njegov kao sunce pred licem mojim, i kao mjesec, koji je osnovan u vijeke; i svjedok je na nebu vjeran.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"08385d844d6fba25":{"kn":"Okrijepljeni svetim darovima molimo Te, Gospodine, Bože naš, da zagovorom blaženoga Alojzija, Tvoga mučenika i biskupa, osjetimo djelovanje svetih tajna, koje izvršujemo.\n<i>Po G. n.</i>","knRef":"Kniewald 1942, str. 790"},"3c8f3a7a5b4b0733":{"t":"Ps 88, 21-23\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja. Neprijatelj biti nemoćan prema njemu, i sin bezakonja neće se usuditi da mu naškodi.\n\nPs 109, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nZakleo se Gospodin i neće se pokajati: ti si svećenik dovijeka po redu Melkisedekovu. <i>Aleluja</i>.","kn":"(Ps. 88, 21-23). Izabrah Davida slu- ,gu moga i pomazah ga uljem svetim; jer ruka moja (Ppmoze njemu i moja ga mišica jača. Neprijatelj mu ne će ništa naškoditi i sin zloće ne će mu nauditi.\n\nAleluja, aleluja (Ps, 109, 4). Zakle se Gospodin i ne će se pokajati: Ti si svećenik dovijeka, po redu Melkisedekovu, aleluja.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"d73994f619e6f543":{"kn":"Obazri se, svemogući Bože, na slabost Tvojih vjernika, koje pritište teret vlastitih čina i podaj, da nas zaštiti slavni zagovor blaženoga Kvirina, Tvoga mučenika i biskupa.\n<i>Po G. n.</i>","knRef":"Kniewald 1942, str. 789"},"dd45cfec89c3d958":{"kn":"Primi, Gospodine, blagostivo žrtve, što Ti ih prinosimo zaslugama blaženoga Kvirina, Tvoga mučenika i biskupa i podaj, da nam ishode neprestanu Tvoju pomoć.\n<i>Po G. n.</i>","knRef":"Kniewald 1942, str. 790"},"c702661d03f57c4c":{"kn":"Okrijepljeni svetim darovima molimo Te, Gospodine, Bože naš, da zagovorom blaženoga Kvirina, Tvoga mučenika i biskupa, osjetimo djelovanje svetih tajna, koje izvršujemo.\n<i>Po G. n.</i>","knRef":"Kniewald 1942, str. 790"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, poeniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:1-7"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ego sum vitis vera: et Pater meus agrícola est. Omnem pálmitem in me non feréntem fructum, tollet eum: et omnem, qui fert fructum, purgábit eum, ut fructum plus áfferat. Jam vos mundi estis propter sermónem, quem locútus sum vobis. Manéte in me: et ego in vobis. Sicut palmes non potest ferre fructum a semetípso, nisi mánserit in vite: sic nec vos, nisi in me manséritis. Ego sum vitis, vos pálmites: qui manet in me, et ego in eo, hic fert fructum multum: quia sine me nihil potéstis fácere. Si quis in me non mánserit, mittétur foras sicut palmes, et aréscet, et cólligent eum, et in ignem mittent, et ardet. Si manséritis in me, et verba mea in vobis mánserint: quodcúmque voluéritis, petétis, et fiet vobis."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde, allelúja, allelúja."}]}}});
